type User = { id: number; name: string; email: string };
class UserRepoA {
  async fetch(id: number): Promise<User> {
    const row = await db.queryRow('select id,name,email from users where id=?', [id]);
    return { id: row.id, name: row.name, email: row.email };
  }
}

